import {analyze,EXAMPLES,markdownPacket,calendarFile} from './engine.js';
const $=id=>document.getElementById(id);let result=null;let completed=new Set();let toastTimer;const storageKey='accesskit.workspace.v1';
function el(tag,props={},children=[]){const n=document.createElement(tag);for(const [key,value] of Object.entries(props)){if(key==='class')n.className=value;else if(key==='text')n.textContent=value;else if(key.startsWith('on'))n.addEventListener(key.slice(2),value);else n.setAttribute(key,value);}for(const child of children)n.append(child);return n;}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function persist(){if(!$('remember').checked)return;try{localStorage.setItem(storageKey,JSON.stringify({title:$('title').value,text:$('notice').value,done:[...completed]}));}catch{toast('This browser could not save your workspace. Download your plan instead.');}}
function sourceButton(id){return el('button',{class:'source-link',text:'View source ↗',onclick:()=>{selectTab('source');const n=$('source-'+id);document.querySelectorAll('.highlight').forEach(x=>x.classList.remove('highlight'));if(n){n.classList.add('highlight');n.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});n.focus({preventScroll:true});}}});}
function selectTab(name){for(const button of document.querySelectorAll('[data-tab]')){const active=button.dataset.tab===name;button.setAttribute('aria-selected',active);button.tabIndex=active?0:-1;$('view-'+button.dataset.tab).hidden=!active;}}
function updateProgress(){const count=result?result.items.filter(i=>completed.has(i.id)).length:0;$('done-count').textContent=count;$('progress-fill').style.width=`${result?.items.length?count/result.items.length*100:0}%`;persist();}
function render(){
 $('empty').hidden=true;$('results').hidden=false;$('plan-title').textContent=$('title').value||'My action plan';$('result-label').textContent='SOURCE-LINKED · RULE-BASED';$('action-count').textContent=result.items.length;$('date-count').textContent=result.deadlines.length;
 $('warnings').replaceChildren();if(result.questions.length){const box=el('section',{class:'warning'},[el('h4',{text:`↗ ${result.questions.length} details to double-check`})]);for(const question of result.questions){const p=el('p',{text:question.text+' '});if(question.sourceIds.length)p.append(sourceButton(question.sourceIds[0]));box.append(p);}$('warnings').append(box);}
 $('view-actions').replaceChildren();
 if(!result.items.length)$('view-actions').append(el('p',{class:'result-caveat',text:'No action phrases detected. Read the original notice; the rules may have missed details.'}));
 for(const group of ['Eligibility','Documents & actions','Next steps','Costs & support','Access details']){const items=result.items.filter(i=>i.group===group);if(!items.length)continue;$('view-actions').append(el('h4',{class:'group-heading',text:group}));for(const item of items){const check=el('input',{type:'checkbox',id:'check-'+item.id});check.checked=completed.has(item.id);const row=el('div',{class:'action-item'+(check.checked?' done':'')});check.addEventListener('change',()=>{if(check.checked)completed.add(item.id);else completed.delete(item.id);row.classList.toggle('done',check.checked);updateProgress();});const meta=el('div',{class:'item-meta'},[sourceButton(item.sourceId)]);if(item.conditional)meta.append(el('span',{class:'tag',text:'CONDITION / EXCEPTION'}));if(item.negative)meta.append(el('span',{class:'tag',text:'READ NEGATION CAREFULLY'}));row.append(check,el('div',{class:'action-body'},[el('label',{for:'check-'+item.id,text:item.text}),meta]));$('view-actions').append(row);}}
 $('view-dates').replaceChildren();if(!result.deadlines.length)$('view-dates').append(el('p',{class:'result-caveat',text:'No written month-and-day dates detected. Numeric dates and recurring schedules need manual review.'}));for(const date of result.deadlines){const card=el('div',{class:'date-card'},[el('span',{class:'tiny',text:date.kind.toUpperCase()}),el('h4',{text:date.label}),el('p',{text:date.text}),sourceButton(date.sourceId)]);if(date.iso){const add=el('button',{class:'secondary',text:'↓ Add date reminder',onclick:()=>{if(confirm(`Have you confirmed ${date.label} against the original notice? This exports an all-day reminder, not the exact closing time.`))download(calendarFile(date.iso,($('title').value||'Notice')+' — verify deadline'),'accesskit-reminder.ics','text/calendar');}});card.append(el('p',{class:'result-caveat',text:'Confirm this date before exporting. Reminders do not encode a closing time.'}),add);}else card.append(el('p',{class:'result-caveat',text:'Year missing or date invalid. Confirm the complete date before making a reminder.'}));$('view-dates').append(card);}
 $('view-source').replaceChildren(...result.source.map(s=>el('div',{id:'source-'+s.id,class:'source-line',tabindex:'-1'},[el('span',{text:s.id}),document.createTextNode(s.text)])));updateProgress();selectTab('actions');
}
function run(reset=true){const text=$('notice').value.trim();if(!text){$('input-status').textContent='Paste a notice or choose an example first.';$('notice').focus();return;}if(reset)completed.clear();result=analyze($('notice').value);render();$('input-status').textContent=`Plan ready. ${result.items.length} source-linked items and ${result.deadlines.length} dates found.`;persist();}
function download(text,name,type='text/markdown'){const url=URL.createObjectURL(new Blob([text],{type}));const a=el('a',{href:url,download:name});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Download prepared.');}
async function copyQuestions(){const text=result.questions.length?result.questions.map((q,i)=>`${i+1}. ${q.text}${q.sourceIds.length?'\nSource: '+result.source.find(s=>s.id===q.sourceIds[0]).text:''}`).join('\n\n'):'No questions were generated. Please still review the original notice.';try{await navigator.clipboard.writeText(text);toast('Questions copied.');}catch{download(text,'accesskit-questions.txt','text/plain');}}
function invalidate(){if(result){result=null;completed.clear();$('results').hidden=true;$('empty').hidden=false;$('result-label').textContent='NOTICE CHANGED';$('input-status').textContent='Notice changed. Make a new plan to refresh your results.';}persist();}
$('analyze').onclick=()=>run();$('notice').addEventListener('input',()=>{$('char-count').textContent=`${$('notice').value.length.toLocaleString()} / 50,000`;invalidate();});$('title').addEventListener('input',()=>{if(result)$('plan-title').textContent=$('title').value||'My action plan';persist();});
for(const button of document.querySelectorAll('[data-example]'))button.onclick=()=>{const example=EXAMPLES[button.dataset.example];$('title').value=example.title;$('notice').value=example.text;$('char-count').textContent=`${example.text.length.toLocaleString()} / 50,000`;run();};
for(const button of document.querySelectorAll('[data-tab]')){button.onclick=()=>selectTab(button.dataset.tab);button.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')];let index=tabs.indexOf(button);index=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[index].dataset.tab);tabs[index].focus();};}
$('download').onclick=()=>download(markdownPacket($('title').value,result,completed),'accesskit-action-plan.md');$('questions').onclick=copyQuestions;$('print').onclick=()=>window.print();
$('reset').onclick=()=>{if($('notice').value&&!confirm('Clear this workspace and start over?'))return;$('title').value='';$('notice').value='';invalidate();$('input-status').textContent='Workspace cleared.';$('char-count').textContent='0 / 50,000';persist();$('notice').focus();};
$('remember').onchange=()=>{try{if($('remember').checked){persist();toast('Workspace will be saved on this device.');}else{localStorage.removeItem(storageKey);toast('Saved copy removed.');}}catch{toast('Browser storage is unavailable.');}};
$('clear-saved').onclick=()=>{try{localStorage.removeItem(storageKey);$('remember').checked=false;toast('Saved copy removed. Current text remains until you start over.');}catch{toast('Browser storage is unavailable.');}};
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>200000){toast('Choose a plain-text file smaller than 200 KB.');e.target.value='';return;}const text=await file.text();if(text.length>50000){toast('This notice exceeds 50,000 characters. Import a shorter text file.');return;}$('notice').value=text;$('title').value=file.name.replace(/\.txt$/i,'');$('char-count').textContent=`${text.length.toLocaleString()} / 50,000`;run();e.target.value='';};
$('about').onclick=()=>$('about-dialog').showModal();for(const b of document.querySelectorAll('.dialog-close'))b.onclick=()=>$('about-dialog').close();
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved&&typeof saved.text==='string'&&saved.text.length<=50000){$('title').value=typeof saved.title==='string'?saved.title.slice(0,160):'';$('notice').value=saved.text;$('remember').checked=true;completed=new Set(Array.isArray(saved.done)?saved.done.filter(x=>typeof x==='string'):[]);$('char-count').textContent=`${saved.text.length.toLocaleString()} / 50,000`;if(saved.text.trim())run(false);}}catch{/* Storage is optional. */}
